  "<a href=\"index.html#fonctionnalites\">Fonctionnalités</a> <a href=\"index.html#video\">Vidéo</a> <a href=\"index.html#offres\">Offres</a> <a href=\"#\" data-lien=\"CONNEXION\">Se connecter</a> <a class=\"bouton bouton-plein\" href=\"inscription.html\">Créer mon espace</a>": "<a href=\"index.html#fonctionnalites\">Funcionalidades</a> <a href=\"index.html#video\">Vídeo</a> <a href=\"index.html#offres\">Planes</a> <a href=\"#\" data-lien=\"CONNEXION\">Iniciar sesión</a> <a class=\"bouton bouton-plein\" href=\"inscription.html\">Crear mi espacio</a>",
